CREATE TABLE `reports` (
  `report_id` int(11) NOT NULL AUTO_INCREMENT,
  `item_id` int(255) NOT NULL,
  `date` date NOT NULL DEFAULT current_timestamp(),
  `brand_name` varchar(255) NOT NULL,
